const STATUS = { collecting: { es: 'Recopilando informaci\u00f3n', en: 'Collecting information' } };
const lang = $json.language || 'es';
return [{ json: { ...$json, status_text: STATUS.collecting[lang] } }];

const { language, current_date, expertise_level, process_definition, form_state, message } = $('Status Text: Collecting').first().json;
const { output: _o, ...defClean } = process_definition || {};
const VERBOSITY = {
  1: `Ask fields one at a time. Include the field description and an example value. Ask all required AND optional fields. Always show a confirmation summary before setting status to confirmed.`,
  2: `Ask 2-3 related fields together. Use field labels only, no descriptions. Ask required fields; ask optional fields only if they seem relevant from context. Auto-confirm when all required fields are collected unless the user asks for a review.`,
  3: `Batch ALL missing required fields in a single message. Skip descriptions, skip examples, skip optional fields entirely. Skip confirmation summary — set status to confirmed immediately when all required fields are present.`,
}[expertise_level] || `Ask 2-3 related fields together. Auto-confirm.`;
const chatInput = `Today: ${current_date}. Respond in: ${language}.

## INTERACTION STYLE
${VERBOSITY}

## PROCESS DEFINITION
${JSON.stringify(defClean, null, 2)}

## CURRENT FORM STATE
${JSON.stringify(form_state, null, 2)}

## USER MESSAGE
"${message}"

## OUTPUT
In progress: {"status": "in_progress", "message": "<question in ${language}>", "form_state": {...updated...}, "processes": null}
All required fields collected: {"status": "confirmed", "message": "<brief in ${language}>", "form_state": {...complete...}, "processes": null}
Cancelled: {"status": "cancelled", "message": "<in ${language}>", "form_state": null, "processes": null}
Lookup needed: {"status": "switch_needed", "message": null, "intent": "<user lookup request>", "form_state": ${JSON.stringify(form_state)}, "processes": null}`;
return [{ json: { chatInput } }];

const STATUS = { submitting: { es: 'Enviando a SAP', en: 'Submitting to SAP' } };
const lang = $json.language || 'es';
return [{ json: { ...$json, status_text: STATUS.submitting[lang] } }];

const { process_definition, form_state, organization, session } = $('Status Text: Submitting').first().json;
const integ = organization?.integration || {};
const authDriver = integ.auth_driver || 'b1s';
const connection = authDriver === 'b1s'
  ? { authDriver, baseUrl: integ.base_url, username: session?.user?.username, password: session?.user?.password, companyDB: session?.database }
  : { authDriver, baseUrl: integ.base_url, token: session?.token };
const method = (process_definition?.api?.method || 'GET').toUpperCase();
const serviceName = process_definition?.api?.service || '';
let operationType;
if (method === 'GET') {
  const keyDef = process_definition?.query?.key;
  const keyValue = keyDef ? form_state?.[keyDef.id] : null;
  operationType = keyValue !== null && keyValue !== undefined ? 'GET_SINGLE' : 'GET_QUERY';
} else {
  operationType = 'POST_CREATE';
}
let data = null;
if (operationType === 'POST_CREATE' && Array.isArray(process_definition?.form?.sections)) {
  const payload = {};
  for (const section of process_definition.form.sections) {
    if (section.multiple) {
      const items = form_state[section.id];
      if (Array.isArray(items) && items.length > 0) {
        payload[section.sap_field] = items.map(item => {
          const line = {};
          for (const field of (section.fields || [])) {
            const val = item[field.id];
            if (val !== null && val !== undefined && val !== '') line[field.sap_field] = val;
          }
          return line;
        });
      }
    } else {
      for (const field of (section.fields || [])) {
        const val = form_state[field.id];
        if (val !== null && val !== undefined && val !== '') payload[field.sap_field] = val;
      }
    }
  }
  const extras = form_state?._extra_fields;
  if (extras && typeof extras === 'object') {
    const allResolved = Object.values(extras).every(v => v !== null && v !== undefined);
    if (allResolved) Object.assign(payload, extras);
  }
  data = payload;
}
const pipelineData = $('Status Text: Submitting').first().json;
return [{ json: { ...pipelineData, sap_operation: operationType, sap_service: serviceName, sap_connection: connection, sap_payload: data } }];

const { language, sap_service, sap_connection, process_definition, form_state } = $json;
const keyDef = process_definition.query.key;
const keyValue = form_state[keyDef.id];
const expand = process_definition.query.expand || [];
const expandLine = expand.length ? `  "expand": ${JSON.stringify(expand)},\n` : '';
const wantsJson = form_state.response_format === 'json';
const successInstruction = wantsJson
  ? `a fenced \`\`\`json code block in the message field containing the full result (after removing null fields) as raw JSON — NOT a bullet list or prose`
  : `Markdown result in ${language}, remove null fields, use schema labels`;
const chatInput = `Call sap_entity_get with these exact parameters:

CALL:
{
  "serviceName": "${sap_service}",
  "entitySet": "",
  "keyValues": { "${keyDef.sap_field}": ${JSON.stringify(keyValue)} },
${expandLine}  "connection": ${JSON.stringify(sap_connection)}
}

Success: {"status": "success", "message": "<${successInstruction}>", "form_state": null, "processes": null}
Not found / Error: {"status": "error", "message": "<user-friendly Markdown in ${language}>", "form_state": null, "processes": null}`;
return [{ json: { chatInput } }];

const { language, sap_service, sap_connection, process_definition, form_state } = $json;
const queryDef = process_definition.query;
const schemaDef = process_definition.schema_definition;
const defaultSelect = Array.isArray(queryDef.select) && queryDef.select.length
  ? queryDef.select
  : schemaDef?.list_select?.length ? schemaDef.list_select
  : schemaDef?.get_select?.length ? schemaDef.get_select
  : null;
const resolvedFilters = (queryDef.filters || [])
  .filter(f => form_state[f.id] !== null && form_state[f.id] !== undefined)
  .map(f => {
    const val = form_state[f.id];
    if (f.type === 'date') return `${f.sap_field} ${f.operator} datetime'${val}T00:00:00'`;
    if (f.type === 'string') {
      const parts = String(val).split(/,|\bor\b/i).map(p => p.trim()).filter(p => p);
      if (f.operator === 'contains') {
        const conds = parts.map(p => `substringof('${p}', ${f.sap_field})`);
        return conds.length > 1 ? '(' + conds.join(' or ') + ')' : conds[0];
      }
      if (parts.length > 1) return '(' + parts.map(p => `${f.sap_field} eq '${p}'`).join(' or ') + ')';
      return `${f.sap_field} eq '${parts[0] || val}'`;
    }
    return `${f.sap_field} ${f.operator} ${val}`;
  });
const effectiveTop = form_state.top || queryDef.top || 20;
const effectiveOrderBy = form_state.order_by || queryDef.order_by;
const requestedFields = form_state.requested_fields || form_state.select_fields;
const fieldMap = (schemaDef?.fields || []).map(f => ({ label: f.label, sap_field: f.sap_field }));
const wantsJson = form_state.response_format === 'json';
const successInstruction = wantsJson
  ? `a fenced \`\`\`json code block in the message field containing the results as a raw JSON array (using schema field ids as keys) — NOT a Markdown table`
  : `Markdown table in ${language}`;
const chatInput = `Call sap_query_entity_set with these parameters.

SERVICE: ${sap_service}
CONNECTION: ${JSON.stringify(sap_connection)}
PRE-BUILT FILTERS (apply as-is, already valid OData v2): ${resolvedFilters.length ? resolvedFilters.join(form_state.match_all ? ' and ' : ' or ') : 'none'}
DEFAULT SELECT: ${defaultSelect ? JSON.stringify(defaultSelect) : 'omit'}
TOP: ${effectiveTop}
ORDERBY: ${effectiveOrderBy ? effectiveOrderBy.map(o => o.field + ' ' + o.direction).join(',') : 'omit'}

USER REQUESTED FIELDS: ${requestedFields ? JSON.stringify(requestedFields) : '"default"'}
If the user specified fields, use this label→sap_field map to resolve them:
${JSON.stringify(fieldMap)}
If default or none specified, use DEFAULT SELECT above.

OData v2 FILTER SYNTAX RULES (SAP B1S):
- String contains: substringof('value', FieldName) — NEVER use FieldName contains 'value'
- String equals: FieldName eq 'value'
- Number equals: FieldName eq 123
- Multiple OR: (substringof('a', F) or substringof('b', F))
- AND: expr1 and expr2
The pre-built filters above already follow this syntax. Pass them to the filter parameter verbatim.

RULES:
- Omit any parameter that is null, empty, or undefined.
- Never pass null values to any parameter.
- Use default select unless user explicitly requested specific fields.
- Render results as a Markdown table using schema labels as column headers, UNLESS the user explicitly asked for JSON/raw format (see OUTPUT below) — in that case render a fenced \`\`\`json code block instead.

Success: {"status": "success", "message": "<${successInstruction}>", "form_state": null, "processes": null}
No records: {"status": "success", "message": "<no records message in ${language}>", "form_state": null, "processes": null}
Error: {"status": "error", "message": "<user-friendly Markdown in ${language}>", "form_state": null, "processes": null}`;
return [{ json: { chatInput } }];

const { language, sap_service, sap_payload, sap_connection } = $json;
const chatInput = `Call sap_entity_create with these exact parameters. Do not modify anything:

CALL:
{
  "serviceName": "${sap_service}",
  "entitySet": "",
  "data": ${JSON.stringify(sap_payload)},
  "connection": ${JSON.stringify(sap_connection)}
}

Success: {"status": "success", "message": "<Markdown result in ${language}>", "form_state": null, "processes": null}
ACTION REQUIRED: {"status": "action_required", "message": "<friendly in ${language}>", "form_state": {"_extra_fields": {"<field>": null}}, "processes": null}
Error: {"status": "error", "message": "<user-friendly Markdown in ${language}>", "form_state": null, "processes": null}`;
return [{ json: { chatInput } }];

const errorText = ($json.error?.message || String($json.error || '')).trim();
const type = /rate.?limit|tokens.?per.?min|TPM|too.?large/i.test(errorText) ? 'RATE_LIMIT'
  : /parse|json|syntax/i.test(errorText) ? 'PARSE_ERROR'
  : /not.?found|404/i.test(errorText) ? 'NOT_FOUND'
  : /unauthorized|403|401/i.test(errorText) ? 'AUTH_ERROR'
  : 'UNKNOWN_ERROR';
return [{ json: { ...$json, error_type: type, raw_error: errorText } }];

const { error_type, language, expertise_level } = $json;
const isExpert = expertise_level === 3;
const MSG = {
  RATE_LIMIT:    { es: 'La b\u00fasqueda devolvi\u00f3 demasiados datos. Intenta con un criterio m\u00e1s espec\u00edfico.', en: 'The search returned too many results. Try a more specific criteria.' },
  PARSE_ERROR:   { es: 'Hubo un error procesando la respuesta. Intenta de nuevo.', en: 'There was an error processing the response. Please try again.' },
  NOT_FOUND:     { es: 'No se encontr\u00f3 la definici\u00f3n del proceso. Intenta de nuevo.', en: 'The process definition could not be loaded. Please try again.' },
  AUTH_ERROR:    { es: 'Error de autenticaci\u00f3n. Contacta al administrador.', en: 'Authentication error. Please contact the administrator.' },
  UNKNOWN_ERROR: { es: isExpert ? $json.raw_error : 'Algo sali\u00f3 mal. Intenta de nuevo o contacta soporte.', en: isExpert ? $json.raw_error : 'Something went wrong. Please try again or contact support.' },
};
const lang = language || 'es';
const message = MSG[error_type]?.[lang] || MSG.UNKNOWN_ERROR[lang];
const clearState = error_type === 'AUTH_ERROR';
return [{ json: {
  ...$json,
  message,
  form_state: clearState ? null : $json.form_state,
  process_id: clearState ? null : $json.process_id,
  process_definition: clearState ? null : $json.process_definition,
  error: error_type,
  responde: true,
}}];

const raw = $input.first().json.output || '';
let content;
try {
  content = JSON.parse(raw.trim());
} catch {
  try {
    const stripped = raw.replace(/^```json\n?/, '').replace(/\n?```$/, '').trim();
    content = JSON.parse(stripped);
  } catch {
    content = { status: 'error', message: raw || 'Could not parse agent response', form_state: null, processes: null };
  }
}
return [{ json: { ...$input.first().json, _parsed: content, _status: content.status } }];

const base = $('Resolve Stack Resume').first().json;
const content = $json._parsed;
const stack = base.process_stack || [];
const mergedFormState = { ...(base.form_state || {}), ...(content.form_state || {}) };
const newEntry = base.process_id
  ? { process_id: base.process_id, process_definition: base.process_definition, form_state: mergedFormState }
  : null;
return [{ json: {
  ...base,
  process_id: null, process_definition: null, form_state: null, pending_processes: null,
  process_stack: newEntry ? [...stack, newEntry] : stack,
  message: content.intent,
  switch_intent: false, responde: false,
}}];

const base = $('Status Text: Finding').first().json;
const content = $json._parsed;
const ref = base.github_tag || 'main';
const orgSlug = base.organization?.slug || '';
const pathSegs = content.path.split('/');
const filename = pathSegs[pathSegs.length - 1];
const module = content.module || pathSegs[pathSegs.length - 2] || '';
const pathPrefix = pathSegs[0] || '';
return [{ json: {
  ...base,
  matched_entry: content,
  standard_path: content.path,
  override_path: `${pathPrefix}/${orgSlug}/${module}/${filename}`,
  github_ref: ref,
  github_api_base: `https://api.github.com/repos/${base.github_owner}/${base.github_repo}/contents`,
  responde: false,
}}];

let base;
try { const d = $('Decode & Set Schema').first().json; if (d?.process_id) base = d; } catch(e) {}
if (!base) { try { const d = $('Status Text: Finding').first().json; if (d?.organization) base = d; } catch(e) {} }
if (!base) base = $('Resolve Stack Resume').first().json;
const content = $json._parsed;
const mergedFormState = { ...(base.form_state || {}), ...(content.form_state || {}), ready: true };
return [{ json: { ...base, form_state: mergedFormState, message: content.message, responde: false } }];

let base;
try { const d = $('Decode & Set Schema').first().json; if (d?.process_id) base = d; } catch(e) {}
if (!base) { try { const d = $('Status Text: Finding').first().json; if (d?.organization) base = d; } catch(e) {} }
if (!base) base = $('Resolve Stack Resume').first().json;
const content = $json._parsed;
const extras = content.form_state?._extra_fields || {};
const updatedFormState = {
  ...(base.form_state || {}),
  ready: false,
  _extra_fields: { ...(base.form_state?._extra_fields || {}), ...extras },
};
return [{ json: { ...base, form_state: updatedFormState, message: content.message, responde: false } }];

let base;
try { const d = $('Decode & Set Schema').first().json; if (d?.process_id) base = d; } catch(e) {}
if (!base) { try { const d = $('Status Text: Finding').first().json; if (d?.organization) base = d; } catch(e) {} }
if (!base) base = $('Resolve Stack Resume').first().json;
const content = $json._parsed;
const stack = base.process_stack || [];
const lang = base.language || 'es';
if (stack.length > 0) {
  const askMsg = lang === 'en'
    ? '**Done!** Do you want to continue with your previous request?'
    : '**Listo!** \u00bfDeseas continuar con tu solicitud anterior?';
  const combinedMessage = content.message ? content.message + '\n\n---\n\n' + askMsg : askMsg;
  return [{ json: {
    ...base,
    process_id: null, process_definition: null, form_state: null,
    process_stack: stack, awaiting_stack_resume: true, reset_process: true,
    message: combinedMessage, responde: true,
  } }];
}
return [{ json: { ...base, process_id: null, process_definition: null, form_state: null, process_stack: [], awaiting_stack_resume: false, reset_process: true, message: content.message, responde: true } }];

let base;
try { const d = $('Decode & Set Schema').first().json; if (d?.process_id) base = d; } catch(e) {}
if (!base) { try { const d = $('Status Text: Finding').first().json; if (d?.organization) base = d; } catch(e) {} }
if (!base) base = $('Resolve Stack Resume').first().json;
const content = $json._parsed;
const mergedFormState = { ...(base.form_state || {}), ...(content.form_state || {}) };
return [{ json: { ...base, form_state: mergedFormState, message: content.message, responde: true } }];

let base;
try { const d = $('Decode & Set Schema').first().json; if (d?.process_id) base = d; } catch(e) {}
if (!base) { try { const d = $('Status Text: Finding').first().json; if (d?.organization) base = d; } catch(e) {} }
if (!base) base = $('Parse & Enrich').first().json;
const content = $json._parsed;
return [{ json: { ...base, processes: content.processes ?? null, pending_processes: content.processes ?? null, message: content.message, responde: true } }];

let base;
try { const d = $('Decode & Set Schema').first().json; if (d?.process_id) base = d; } catch(e) {}
if (!base) { try { const d = $('Status Text: Finding').first().json; if (d?.organization) base = d; } catch(e) {} }
if (!base) base = $('Resolve Stack Resume').first().json;
const content = $json._parsed;
return [{ json: { ...base, message: content.message, error: 'AGENT_ERROR', form_state: base.form_state, responde: true } }];

const fileData = $input.first().json;
const statusCode = fileData.statusCode;
let pipelineBase;
try { const d = $('Handler: Match').first().json; if (d?.standard_path) pipelineBase = d; } catch(e) {}
if (!pipelineBase) pipelineBase = $('Parse & Enrich').first().json;
if (fileData.error || (statusCode && statusCode >= 400)) {
  return [{ json: { ...pipelineBase, error: 'NOT_FOUND', message: 'No se encontr\u00f3 la definici\u00f3n del proceso.', responde: false } }];
}
const rawContent = (fileData.body || fileData).content;
let processDefinition;
try {
  const decoded = Buffer.from(rawContent.replace(/\n/g, ''), 'base64').toString('utf-8');
  processDefinition = JSON.parse(decoded);
} catch (e) {
  return [{ json: { ...pipelineBase, error: 'NOT_FOUND', message: 'Error al parsear la definici\u00f3n del proceso.', responde: false } }];
}
const fullObj = { ...pipelineBase };
fullObj.process_definition = processDefinition;
fullObj.process_id = processDefinition.id;
const filePath = (fileData.body || fileData).path || '';
const fileDir = filePath ? filePath.substring(0, filePath.lastIndexOf('/')) : '';
const owner = fullObj.github_owner || '';
const repo = fullObj.github_repo || '';
const githubRef = fullObj.github_tag || 'main';
const schemaSlug = processDefinition.schema || '';
fullObj.schema_fetch_url = (fileDir && schemaSlug && owner && repo)
  ? `https://api.github.com/repos/${owner}/${repo}/contents/${fileDir}/${schemaSlug}.json?ref=${githubRef}`
  : null;
return [{ json: { ...fullObj, responde: false } }];

const fileData = $input.first().json;
const prevData = $('Decode & Set Process').first().json;
if (!prevData.schema_fetch_url || fileData.error || (fileData.statusCode && fileData.statusCode >= 400)) {
  return [{ json: { ...prevData, responde: false } }];
}
const rawContent = (fileData.body || fileData).content;
let schemaDefinition = null;
try {
  const decoded = Buffer.from(rawContent.replace(/\n/g, ''), 'base64').toString('utf-8');
  schemaDefinition = JSON.parse(decoded);
} catch (e) {
  return [{ json: { ...prevData, responde: false } }];
}
const output = { ...prevData };
if (output.process_definition && schemaDefinition) {
  output.process_definition = { ...output.process_definition, schema_definition: schemaDefinition };
}
return [{ json: { ...output, responde: false } }];

const base = $('Parse & Enrich').first().json;
const update = $input.first().json;
// reset_process means a handler (e.g. Handler: Completion parking the active process)
// is intentionally setting process_id/process_definition/form_state to null — without
// this flag, '??' would treat that null as "unknown" and silently fall back to the
// stale inbound value, which is exactly the bug that let a cleared process_id keep
// reappearing on later turns.
const resetProcess = update.reset_process === true;
const normalized = {
  ...base,
  process_id: resetProcess ? (update.process_id ?? null) : (update.process_id ?? base.process_id ?? null),
  process_definition: resetProcess ? (update.process_definition ?? null) : (update.process_definition ?? base.process_definition ?? null),
  form_state: resetProcess ? (update.form_state ?? null) : (update.form_state ?? base.form_state ?? null),
  process_stack: update.process_stack ?? base.process_stack ?? [],
  processes: update.processes ?? null,
  pending_processes: update.pending_processes ?? null,
  message: update.message || null,
  error: update.error || null,
  responde: update.responde ?? false,
  awaiting_stack_resume: update.awaiting_stack_resume ?? base.awaiting_stack_resume ?? false,
  reset_process: resetProcess,
};
['switch_intent', 'selection_resolved', 'status_text', 'sap_operation', 'sap_payload', 'sap_connection', 'sap_service',
 'error_type', 'raw_error', 'chatInput', 'github_api_base', 'standard_path', 'override_path',
 'schema_fetch_url', 'matched_entry', '_parsed', '_status'].forEach(k => delete normalized[k]);
return [{ json: normalized }];

const d = $input.first().json;
return [{ json: {
