  text: d.message || '',
  type: (d.error && !['NO_MATCH', 'MULTIPLE_PROCESSES', 'AGENT_ERROR'].includes(d.error)) ? 'alert' : 'agent',
  state: {
    form_state: d.form_state ?? null,
    process_id: d.process_id ?? null,
    process_definition: d.process_definition ?? null,
    pending_processes: d.processes ?? null,
    process_stack: d.process_stack ?? [],
    awaiting_stack_resume: d.awaiting_stack_resume ?? false,
    reset_process: d.reset_process === true,
  },
  processes: d.processes ?? null,
